1	//! Which props of a component evidence puts forward (ADR 0028, section A).
2	//!
3	//! [`decide`] is the one place the rules are combined: it takes the [`Evidence`] each lane gathers for the members a
4	//! component's props type reaches and says, for each member, whether it is a typed row, a name in its collapsed
5	//! layer's `used` list, left in that layer, or decided as today because the body says nothing. It is pure and total:
6	//! no I/O, no name lists, and its output follows the order of the members it is given. Nothing calls it yet; the
7	//! lanes are wired after the collapse PR merges (ADR 0028, slice T7).
8	#![cfg_attr(not(test), expect(dead_code, reason = "wired into both lanes by ADR 0028 slice T7"))]
9	
10	mod call_sites;
11	mod forwarding;
12	mod props_type;
13	
14	use std::collections::BTreeSet;
15	
16	/// Everything known about the members one component's props type reaches.
17	#[derive(Debug, Clone, Default, PartialEq, Eq)]
18	pub(crate) struct Evidence {
19	    /// The members, in the order the props type reaches them; [`Shown`] keeps this order. A name repeated is placed
20	    /// once, by its first member.
21	    pub(crate) members: Vec<Member>,
22	    /// What the component's own function body does with its props; `None` when it has no function of its own.
23	    pub(crate) body: Option<Body>,
24	    /// The props passed at the component's JSX call sites across the project.
25	    pub(crate) call_sites: CallSites,
26	    /// The names set in the `args` of the component's stories. Any one of them counts: stories have no floor.
27	    pub(crate) story_args: Vec<String>,
28	}
29	
30	/// One member the props type reaches, with the signals its declaration gives.
31	#[derive(Debug, Clone, Default, PartialEq, Eq)]
32	pub(crate) struct Member {
33	    /// The member's name. Only compared with other names in the same [`Evidence`], never with a list.
34	    pub(crate) name: String,
35	    /// The props type declares it itself, not through an inherited source.
36	    pub(crate) own: bool,
37	    /// A key a `Pick<X, …>` names.
38	    pub(crate) picked: bool,
39	    /// It redeclares or narrows a base member.
40	    pub(crate) overrides: bool,
41	    /// It is not optional.
42	    pub(crate) required: bool,
43	    /// Its declaration carries a `@default` tag.
44	    pub(crate) default_tag: bool,
45	    /// It carries a JSDoc comment: orders the rows, never shows a member.
46	    pub(crate) documented: bool,
47	    /// Its type is a union of literals: orders the rows, never shows a member.
48	    pub(crate) literal_union: bool,
49	    /// Declared by `@types/react`, or reaching the component only through a spread onto a DOM tag. Computed by the
50	    /// lane from the declaring path, never from the name.
51	    pub(crate) ambient: bool,
52	}
53	
54	/// What a component's function body does with its props, read from the syntax alone.
55	#[derive(Debug, Clone, Default, PartialEq, Eq)]
56	pub(crate) struct Body {
57	    /// The props the body reads. Complete only when `handed_on` is false.
58	    pub(crate) reads: Vec<String>,
59	    /// The props destructured with a default value.
60	    pub(crate) defaulted: Vec<String>,
61	    /// The JSX elements the body writes, in source order.
62	    pub(crate) elements: Vec<Element>,
63	    /// The props object or a rest binding escapes in a way the syntax cannot follow: what the body says still holds,
64	    /// but its silence about a prop is unknown, never guessed.
65	    pub(crate) handed_on: bool,
66	}
67	
68	/// One JSX element a component body writes.
69	#[derive(Debug, Clone, PartialEq, Eq)]
70	pub(crate) struct Element {
71	    /// What the tag resolves to.
72	    pub(crate) target: Target,
73	    /// Its attributes in source order, so a named attribute's place before or after a spread is kept.
74	    pub(crate) attributes: Vec<Attribute>,
75	}
76	
77	/// What a JSX tag resolves to.
78	#[derive(Debug, Clone, PartialEq, Eq)]
79	pub(crate) enum Target {
80	    /// A host element: a spread onto it passes only ambient DOM attributes.
81	    Dom,
82	    /// A component resolved by symbol and import, with the names of its own non-ambient props.
83	    Component(Vec<String>),
84	    /// A component tag that did not resolve: a spread onto it leaves the body's evidence unknown.
85	    Unresolved,
86	}
87	
88	/// One attribute of a JSX element.
89	#[derive(Debug, Clone, PartialEq, Eq)]
90	pub(crate) enum Attribute {
91	    /// `name={value}`, with the component's own prop the value is, when it is exactly one.
92	    Named {
93	        /// The attribute's name.
94	        name: String,
95	        /// The component's prop the value is, if it is exactly one. Kept from the extractor's facts; [`decide`] gives
96	        /// it no weight (an attribute valued with an own prop adds nothing).
97	        prop: Option<String>,
98	    },
99	    /// `{...value}`.
100	    Spread(SpreadOf),
101	}
102	
103	/// What a JSX spread attribute spreads.
104	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
105	pub(crate) enum SpreadOf {
106	    /// The props object, whole.
107	    Props,
108	    /// A rest binding of the props object.
109	    Rest,
110	    /// Any other expression: no evidence about the props.
111	    Other,
112	}
113	
114	/// How often each prop is passed at a component's JSX call sites.
115	#[derive(Debug, Clone, Default, PartialEq, Eq)]
116	pub(crate) struct CallSites {
117	    /// The number of call sites.
118	    pub(crate) sites: u32,
119	    /// Each prop passed at them, with the number of sites passing it.
120	    pub(crate) passed: Vec<(String, u32)>,
121	}
122	
123	impl CallSites {
124	    /// Whether `count` of the sites reach the floor of `max(2, 20%)` of them.
125	    fn at_floor(&self, count: u32) -> bool {
126	        count >= 2 && u64::from(count) * 5 >= u64::from(self.sites)
127	    }
128	}
129	
130	/// Where [`decide`] puts each member, every list in the order of [`Evidence::members`], except that `rows` puts the
131	/// documented and literal-union members first.
132	#[derive(Debug, Clone, Default, PartialEq, Eq)]
133	pub(crate) struct Shown {
134	    /// Typed rows.
135	    pub(crate) rows: Vec<String>,
136	    /// Ambient members named in their collapsed layer's `used` list.
137	    pub(crate) used: Vec<String>,
138	    /// Members left in their collapsed layer.
139	    pub(crate) collapsed: Vec<String>,
140	    /// Members with no signal whose body evidence is incomplete: listed or collapsed as today, so missing evidence
141	    /// never hides more than today does.
142	    pub(crate) as_today: Vec<String>,
143	}
144	
145	/// Decides, from the evidence alone, where each member of a component's props goes.
146	pub(crate) fn decide(evidence: &Evidence) -> Shown {
147	    let body = evidence.body.as_ref();
148	    let complete = body.is_some_and(Body::is_complete);
149	    let facts = |names: fn(&Body) -> &[String]| -> BTreeSet<&str> {
150	        body.map(|body| names(body).iter().map(String::as_str).collect()).unwrap_or_default()
151	    };
152	    let (reads, defaulted) = (facts(|body| &body.reads), facts(|body| &body.defaulted));
153	    let forwarded = body.map(Body::forwarded).unwrap_or_default();
154	    let passed: BTreeSet<&str> = evidence
155	        .call_sites
156	        .passed
157	        .iter()
158	        .filter(|(_, count)| evidence.call_sites.at_floor(*count))
159	        .map(|(name, _)| name.as_str())
160	        .chain(evidence.story_args.iter().map(String::as_str))
161	        .collect();
162	    let mut shown = Shown::default();
163	    let mut ordered_rows = Vec::new();
164	    let mut placed = BTreeSet::new();
165	    for member in &evidence.members {
166	        let name = member.name.as_str();
167	        if !placed.insert(name) {
168	            continue;
169	        }
170	        let read = reads.contains(name);
171	        let defaulted = member.default_tag || defaulted.contains(name);
172	        let declared = member.own || member.picked || member.overrides || member.required || defaulted;
173	        let list = if declared || passed.contains(name) || (!member.ambient && (read || forwarded.contains(name))) {
174	            ordered_rows.push((!(member.documented || member.literal_union), member.name.clone()));
175	            continue;
176	        } else if member.ambient && read {
177	            &mut shown.used
178	        } else if !complete {
179	            &mut shown.as_today
180	        } else {
181	            &mut shown.collapsed
182	        };
183	        list.push(member.name.clone());
184	    }
185	    ordered_rows.sort_by_key(|(plain, _)| *plain);
186	    shown.rows = ordered_rows.into_iter().map(|(_, name)| name).collect();
187	    shown
188	}
189	
190	impl Body {
191	    /// Whether the body's evidence is complete, so that a prop it never mentions is known to be unused: nothing handed
192	    /// on, and no spread of the props onto a tag that did not resolve. What an incomplete body does say (a read, a
193	    /// default, a forward) is still certain; only its silence is unknown.
194	    fn is_complete(&self) -> bool {
195	        !self.handed_on
196	            && !self.elements.iter().any(|element| {
197	                element.target == Target::Unresolved
198	                    && element.attributes.iter().any(|attribute| attribute.spreads_props())
199	            })
200	    }
201	
202	    /// The props a spread of the props object or a rest binding passes one hop on to a component: the component's own
203	    /// props, minus those an attribute after the spread fixes. Spreads onto DOM tags pass nothing.
204	    fn forwarded(&self) -> BTreeSet<&str> {
205	        let mut forwarded = BTreeSet::new();
206	        for element in &self.elements {
207	            let Target::Component(own) = &element.target else { continue };
208	            for (at, attribute) in element.attributes.iter().enumerate() {
209	                if !attribute.spreads_props() {
210	                    continue;
211	                }
212	                let fixed: BTreeSet<&str> = element.attributes[at + 1..]
213	                    .iter()
214	                    .filter_map(|after| match after {
215	                        Attribute::Named { name, .. } => Some(name.as_str()),
216	                        Attribute::Spread(_) => None,
217	                    })
218	                    .collect();
219	                forwarded.extend(own.iter().map(String::as_str).filter(|name| !fixed.contains(name)));
220	            }
221	        }
222	        forwarded
223	    }
224	}
225	
226	impl Attribute {
227	    /// Whether the attribute spreads the props object or a rest binding of it.
228	    fn spreads_props(&self) -> bool {
229	        matches!(self, Self::Spread(SpreadOf::Props | SpreadOf::Rest))
230	    }
231	}
232	
233	#[cfg(test)]
234	mod tests {
235	    use super::*;
236	
237	    /// Where a member went, for the tables.
238	    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
239	    enum Placed {
240	        Row,
241	        Used,
242	        Collapsed,
243	        AsToday,
244	    }
245	
246	    fn inherited(name: &str) -> Member {
247	        Member { name: name.to_owned(), ..Member::default() }
248	    }
249	
250	    fn ambient(name: &str) -> Member {
251	        Member { ambient: true, ..inherited(name) }
252	    }
253	
254	    fn strings(names: &[&str]) -> Vec<String> {
255	        names.iter().map(|name| (*name).to_owned()).collect()
256	    }
257	
258	    fn reading(names: &[&str]) -> Body {
259	        Body { reads: strings(names), ..Body::default() }
260	    }
261	
262	    fn named(name: &str, prop: Option<&str>) -> Attribute {
263	        Attribute::Named { name: name.to_owned(), prop: prop.map(str::to_owned) }
264	    }
265	
266	    fn element(target: Target, attributes: Vec<Attribute>) -> Element {
267	        Element { target, attributes }
268	    }
269	
270	    fn with(members: Vec<Member>, body: Option<Body>) -> Evidence {
271	        Evidence { members, body, ..Evidence::default() }
272	    }
273	
274	    fn placed(shown: &Shown, name: &str) -> Option<Placed> {
275	        let lists = [
276	            (&shown.rows, Placed::Row),
277	            (&shown.used, Placed::Used),
278	            (&shown.collapsed, Placed::Collapsed),
279	            (&shown.as_today, Placed::AsToday),
280	        ];
281	        lists.into_iter().find(|(list, _)| list.iter().any(|n| n == name)).map(|(_, placed)| placed)
282	    }
283	
284	    /// One case of a table: its label, its evidence, and where each named member must go.
285	    type Case<'a> = (&'a str, Evidence, &'a [(&'a str, Placed)]);
286	
287	    /// Runs each case and checks where every named member went.
288	    fn table(cases: Vec<Case<'_>>) {
289	        for (case, evidence, expected) in cases {
290	            let shown = decide(&evidence);
291	            for (name, want) in expected {
292	                assert_eq!(placed(&shown, name), Some(*want), "{case}: {name}");
293	            }
294	        }
295	    }
296	
297	    #[test]
298	    fn an_inherited_member_the_body_never_reads_stays_in_its_layer() {
299	        let evidence = with(vec![inherited("tone"), inherited("size")], Some(reading(&["size"])));
300	        let shown = decide(&evidence);
301	        assert_eq!(shown.collapsed, ["tone"]);
302	        assert_eq!(shown.rows, ["size"]);
303	    }
304	
305	    #[test]
306	    fn a_member_the_props_type_declares_itself_is_always_a_row() {
307	        let own = |member: Member| Member { own: true, ..member };
308	        table(vec![
309	            ("never read", with(vec![own(inherited("a"))], Some(Body::default())), &[("a", Placed::Row)]),
310	            ("unknown body", with(vec![own(inherited("a"))], None), &[("a", Placed::Row)]),
311	            ("ambient", with(vec![own(ambient("a"))], Some(Body::default())), &[("a", Placed::Row)]),
312	        ]);
313	    }
314	
315	    #[test]
316	    fn a_picked_key_is_a_row_and_its_unpicked_siblings_are_not() {
317	        let picked = Member { picked: true, ..inherited("a") };
318	        table(vec![(
319	            "Pick<X, 'a'>",
320	            with(vec![picked, inherited("b")], Some(Body::default())),
321	            &[("a", Placed::Row), ("b", Placed::Collapsed)],
322	        )]);
323	    }
324	
325	    #[test]
326	    fn a_member_that_overrides_or_narrows_a_base_member_is_a_row() {
327	        let overriding = |member: Member| Member { overrides: true, ..member };
328	        table(vec![
329	            ("inherited", with(vec![overriding(inherited("a"))], Some(Body::default())), &[("a", Placed::Row)]),
330	            ("ambient", with(vec![overriding(ambient("a"))], Some(Body::default())), &[("a", Placed::Row)]),
331	        ]);
332	    }
333	
334	    #[test]
335	    fn a_required_or_defaulted_member_is_a_row() {
336	        let required = Member { required: true, ..inherited("a") };
337	        let tagged = Member { default_tag: true, ..inherited("b") };
338	        let destructured = Body { defaulted: strings(&["c"]), ..Body::default() };
339	        table(vec![(
340	            "required, @default, destructuring default",
341	            with(vec![required, tagged, inherited("c"), inherited("d")], Some(destructured)),
342	            &[("a", Placed::Row), ("b", Placed::Row), ("c", Placed::Row), ("d", Placed::Collapsed)],
343	        )]);
344	    }
345	
346	    #[test]
347	    fn a_doc_comment_or_literal_union_orders_rows_but_never_shows_a_member_alone() {
348	        let documented = |name: &str| Member { documented: true, ..inherited(name) };
349	        let union = |name: &str| Member { literal_union: true, ..inherited(name) };
350	        table(vec![(
351	            "alone",
352	            with(vec![documented("a"), union("b"), Member { documented: true, ..ambient("c") }], Some(Body::default())),
353	            &[("a", Placed::Collapsed), ("b", Placed::Collapsed), ("c", Placed::Collapsed)],
354	        )]);
355	        let evidence = with(vec![inherited("plain"), union("u"), documented("d")], Some(reading(&["plain", "u", "d"])));
356	        assert_eq!(decide(&evidence).rows, ["u", "d", "plain"]);
357	    }
358	
359	    #[test]
360	    fn a_rest_spread_onto_a_dom_tag_is_no_evidence() {
361	        let body =
362	            Body { elements: vec![element(Target::Dom, vec![Attribute::Spread(SpreadOf::Rest)])], ..Body::default() };
363	        table(vec![(
364	            "<div {...rest} />",
365	            with(vec![inherited("a"), ambient("onClick")], Some(body)),
366	            &[("a", Placed::Collapsed), ("onClick", Placed::Collapsed)],
367	        )]);
368	    }
369	
370	    #[test]
371	    fn a_spread_onto_a_component_forwards_its_own_props_one_hop() {
372	        let inner = || Target::Component(strings(&["tone", "size", "variant"]));
373	        let spread =
374	            |attributes: Vec<Attribute>| Body { elements: vec![element(inner(), attributes)], ..Body::default() };
375	        let members = || vec![inherited("tone"), inherited("size"), inherited("variant"), inherited("other")];
376	        let rest = || Attribute::Spread(SpreadOf::Rest);
377	        table(vec![
378	            (
379	                "<Inner {...rest} />",
380	                with(members(), Some(spread(vec![rest()]))),
381	                &[("tone", Placed::Row), ("size", Placed::Row), ("other", Placed::Collapsed)],
382	            ),
383	            (
384	                "<Inner {...props} />",
385	                with(members(), Some(spread(vec![Attribute::Spread(SpreadOf::Props)]))),
386	                &[("variant", Placed::Row), ("other", Placed::Collapsed)],
387	            ),
388	            (
389	                "<Inner tone=\"x\" {...rest} size=\"y\" />: before kept, after subtracted",
390	                with(members(), Some(spread(vec![named("tone", None), rest(), named("size", None)]))),
391	                &[("tone", Placed::Row), ("size", Placed::Collapsed), ("variant", Placed::Row)],
392	            ),
393	            (
394	                "<Inner {...other} />",
395	                with(members(), Some(spread(vec![Attribute::Spread(SpreadOf::Other)]))),
396	                &[("tone", Placed::Collapsed)],
397	            ),
398	        ]);
399	    }
400	
401	    #[test]
402	    fn an_attribute_valued_with_an_own_prop_adds_nothing() {
403	        let body = Body {
404	            elements: vec![element(Target::Component(strings(&["tone"])), vec![named("tone", Some("size"))])],
405	            ..Body::default()
406	        };
407	        table(vec![(
408	            "<Inner tone={size} />",
409	            with(vec![inherited("size"), inherited("tone")], Some(body)),
410	            &[("size", Placed::Collapsed), ("tone", Placed::Collapsed)],
411	        )]);
412	    }
413	
414	    #[test]
415	    fn a_read_member_is_a_row_unless_ambient_then_a_used_name() {
416	        table(vec![(
417	            "reads",
418	            with(vec![inherited("a"), ambient("className"), ambient("id")], Some(reading(&["a", "className"]))),
419	            &[("a", Placed::Row), ("className", Placed::Used), ("id", Placed::Collapsed)],
420	        )]);
421	    }
422	
423	    #[test]
424	    fn a_prop_passed_at_a_fifth_of_the_call_sites_is_a_typed_row() {
425	        let passed = |sites: u32, count: u32| Evidence {
426	            members: vec![inherited("a"), ambient("b")],
427	            body: Some(Body::default()),
428	            call_sites: CallSites { sites, passed: vec![("a".to_owned(), count), ("b".to_owned(), count)] },
429	            story_args: Vec::new(),
430	        };
431	        table(vec![
432	            ("2 of 10", passed(10, 2), &[("a", Placed::Row), ("b", Placed::Row)]),
433	            ("1 of 10", passed(10, 1), &[("a", Placed::Collapsed), ("b", Placed::Collapsed)]),
434	            ("1 of 2: under the floor of 2", passed(2, 1), &[("a", Placed::Collapsed)]),
435	            ("2 of 11: under 20%", passed(11, 2), &[("a", Placed::Collapsed)]),
436	            ("3 of 11", passed(11, 3), &[("a", Placed::Row)]),
437	        ]);
438	    }
439	
440	    #[test]
441	    fn any_story_arg_is_a_typed_row() {
442	        let evidence = Evidence {
443	            members: vec![inherited("a"), ambient("b"), inherited("c")],
444	            body: Some(Body::default()),
445	            call_sites: CallSites { sites: 50, passed: Vec::new() },
446	            story_args: strings(&["a", "b"]),
447	        };
448	        table(vec![("one story", evidence, &[("a", Placed::Row), ("b", Placed::Row), ("c", Placed::Collapsed)])]);
449	    }
450	
451	    #[test]
452	    fn an_unknown_body_is_never_guessed() {
453	        let said = || Body { defaulted: strings(&["e"]), ..reading(&["a"]) };
454	        let handed_on = Body { handed_on: true, ..said() };
455	        let unresolved =
456	            Body { elements: vec![element(Target::Unresolved, vec![Attribute::Spread(SpreadOf::Rest)])], ..said() };
457	        let members = || {
458	            vec![
459	                inherited("a"),
460	                inherited("b"),
461	                ambient("c"),
462	                Member { required: true, ..inherited("d") },
463	                inherited("e"),
464	            ]
465	        };
466	        // What an incomplete body says still holds; only its silence is unknown, ambient or not.
467	        let incomplete: &[(&str, Placed)] = &[
468	            ("a", Placed::Row),
469	            ("b", Placed::AsToday),
470	            ("c", Placed::AsToday),
471	            ("d", Placed::Row),
472	            ("e", Placed::Row),
473	        ];
474	        let none: &[(&str, Placed)] = &[
475	            ("a", Placed::AsToday),
476	            ("b", Placed::AsToday),
477	            ("c", Placed::AsToday),
478	            ("d", Placed::Row),
479	            ("e", Placed::AsToday),
480	        ];
481	        table(vec![
482	            ("handed on", with(members(), Some(handed_on)), incomplete),
483	            ("spread onto an unresolved tag", with(members(), Some(unresolved)), incomplete),
484	            ("no function of its own", with(members(), None), none),
485	        ]);
486	    }
487	
488	    #[test]
489	    fn names_carry_no_meaning_and_order_follows_the_members() {
490	        let evidence = |names: [&str; 4]| {
491	            with(
492	                vec![inherited(names[0]), ambient(names[1]), inherited(names[2]), ambient(names[3])],
493	                Some(reading(&[names[2], names[3]])),
494	            )
495	        };
496	        let plain = decide(&evidence(["a", "b", "c", "d"]));
497	        let familiar = decide(&evidence(["className", "style", "onClick", "children"]));
498	        assert_eq!((plain.rows, plain.used, plain.collapsed), (strings(&["c"]), strings(&["d"]), strings(&["a", "b"])));
499	        assert_eq!(familiar.rows, ["onClick"]);
500	        assert_eq!(familiar.used, ["children"]);
501	        assert_eq!(familiar.collapsed, ["className", "style"]);
502	        assert_eq!(decide(&Evidence::default()), Shown::default());
503	        let twice = decide(&with(vec![inherited("a"), ambient("a")], Some(reading(&["a"]))));
504	        assert_eq!((twice.rows, twice.used), (strings(&["a"]), Vec::new()));
505	    }
506	}
